/* Southern Grid Transmission (Energy & utilities) - source database seed for the pipeline Copy demo
   Plays the role of: Enterprise Asset Management (on-prem SQL Server)
   Run this whole script ONCE in a Fabric SQL database (or Azure SQL / SQL Server). Then release the days in order:
       EXEC src.usp_release_day 1;   -- before the first pipeline run
       EXEC src.usp_release_day 2;   -- before the second run
       EXEC src.usp_release_day 3;   -- before the third run (adds a new column = schema drift)
   Generated by tools/build_kit.py - all data is fictional. */
IF SCHEMA_ID('src') IS NULL EXEC('CREATE SCHEMA src');
GO
DROP TABLE IF EXISTS src.assets; DROP TABLE IF EXISTS src.work_orders; DROP TABLE IF EXISTS src.stage_assets; DROP TABLE IF EXISTS src.stage_work_orders;
CREATE TABLE src.assets (asset_id INT NOT NULL, asset_tag NVARCHAR(30), asset_name NVARCHAR(100), asset_class NVARCHAR(30), region NVARCHAR(40), status NVARCHAR(30), criticality INT, rating_mva DECIMAL(12,1), install_date DATE, last_modified DATETIME2(0), CONSTRAINT pk_assets PRIMARY KEY (asset_id));
CREATE TABLE src.work_orders (wo_id INT NOT NULL, asset_id INT, wo_type NVARCHAR(30), priority INT, status NVARCHAR(30), raised_ts DATETIME2(0), completed_ts DATETIME2(0), cost_aud DECIMAL(12,2), labour_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0), CONSTRAINT pk_work_orders PRIMARY KEY (wo_id));
CREATE TABLE src.stage_assets (release_day INT NOT NULL, asset_id INT, asset_tag NVARCHAR(30), asset_name NVARCHAR(100), asset_class NVARCHAR(30), region NVARCHAR(40), status NVARCHAR(30), criticality INT, rating_mva DECIMAL(12,1), install_date DATE, last_modified DATETIME2(0), asset_owner_group NVARCHAR(50));
CREATE TABLE src.stage_work_orders (release_day INT NOT NULL, wo_id INT, asset_id INT, wo_type NVARCHAR(30), priority INT, status NVARCHAR(30), raised_ts DATETIME2(0), completed_ts DATETIME2(0), cost_aud DECIMAL(12,2), labour_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0));
GO
GO
CREATE OR ALTER PROCEDURE src.usp_release_day @day INT
AS
BEGIN
    SET NOCOUNT ON;
    IF @day >= 3 AND COL_LENGTH('src.assets', 'asset_owner_group') IS NULL
        EXEC('ALTER TABLE src.assets ADD asset_owner_group NVARCHAR(50) NULL');
    DELETE t FROM src.assets t WHERE EXISTS (SELECT 1 FROM src.stage_assets s WHERE s.release_day = @day AND s.asset_id = t.asset_id);
    IF @day >= 3
        EXEC('UPDATE t SET t.asset_owner_group = s.asset_owner_group FROM src.assets t JOIN src.stage_assets s ON s.asset_id = t.asset_id AND s.release_day = 3');
    DELETE t FROM src.work_orders t WHERE EXISTS (SELECT 1 FROM src.stage_work_orders s WHERE s.release_day = @day AND s.wo_id = t.wo_id);
    SELECT @day AS released_day, (SELECT COUNT(*) FROM src.assets) AS assets, (SELECT COUNT(*) FROM src.work_orders) AS work_orders;
END;
GO
